// Accords : notation française → anglaise (La m → Am, Do#° → C#°), pour les pavés d'accords de l'éditeur
const NOTES = { 'Do': 'C', 'Do#': 'C#', 'Ré': 'D', 'Ré#': 'D#', 'Mi': 'E', 'Fa': 'F', 'Fa#': 'F#', 'Sol': 'G', 'Sol#': 'G#', 'La': 'A', 'La#': 'A#', 'Si': 'B' };
for (const [fr, en] of Object.entries(NOTES)) {
  for (const [sfx, esf] of [['', ''], [' m', 'm'], ['°', '°']]) {
    exact[fr + sfx] = en + esf;
    exact[`${fr}${sfx} — clic : poser l'accord à la suite · Maj + clic : avec la 7e`] = `${en}${esf} — click: add the chord next · Shift + click: with the 7th`;
  }
}

